INSERT INTO rule_version (id, jurisdiction, version, name, rule_type, effective_from, effective_to, status, institution, ruleset_file, published_at, author, changelog) VALUES
  ('rv-mo-2026-1', 'MO', 'MO-SA-2026.1', '澳门资本充足率监管规则（权重法）', '资本充足率', '2026-01-01', NULL, 'published', '澳门分行（法人）', 'ruleset_cn_mo.json', '2025-12-18 09:30', '规则管理员 · 陈敏', '在 2025 版基础上调整商用房地产依赖现金流档位的权重下限，并对齐资产担保债券的资产池合格条件。'),
  ('rv-mo-2025-2', 'MO', 'MO-SA-2025.2', '澳门资本充足率监管规则（权重法）· 历史版', '资本充足率', '2025-07-01', '2025-12-31', 'superseded', '澳门分行（法人）', 'ruleset_cn_mo.json', '2025-06-20 14:10', '规则管理员 · 陈敏', '历史版本，已被 MO-SA-2026.1 取代。历史计量批次仍按本版规则还原。'),
  ('rv-mo-2026-draft', 'MO', 'MO-SA-2026.2-draft', '澳门资本充足率监管规则（征求意见稿）', '资本充足率', '2026-07-01', NULL, 'draft', '澳门分行（法人）', 'ruleset_cn_mo.json', '—', '规则管理员 · 陈敏', '草稿：拟新增本地中小企业专项分类，尚在征求意见，未发布。'),
  ('rv-cn-2026-1', 'CN', 'CN-SA-2026.1', '内地资本管理办法（权重法）', '资本充足率', '2026-01-01', NULL, 'published', '总行（法人）', 'ruleset_cn.json', '2025-11-30 10:00', '规则管理员 · 李伟', '首次发布，建立内地风险暴露分类与风险权重规则基线。'),
  ('rv-cn-2026-review', 'CN', 'CN-SA-2026.1-review', '内地资本管理办法（修订送审稿）', '资本充足率', '2026-10-01', NULL, 'reviewing', '总行（法人）', 'ruleset_cn.json', '—', '规则管理员 · 李伟', '审核中：投资级公司认定条件拟收紧，等待风险条线会签。'),
  ('rv-hk-2025-2', 'HK', 'HK-SA-2025.2', '香港银行业（资本）规则（权重法）', '资本充足率', '2025-07-01', NULL, 'published', '香港分行', 'ruleset_hk.json', '2025-06-15 16:40', '规则管理员 · 黄嘉怡', '按当地口径维护监管零售与中小企业权重，独立于内地与澳门版本。'),
  ('rv-hk-2024-1', 'HK', 'HK-SA-2024.1', '香港银行业（资本）规则（权重法）· 已停用', '资本充足率', '2024-01-01', '2025-06-30', 'disabled', '香港分行', 'ruleset_hk.json', '2023-12-20 11:20', '规则管理员 · 黄嘉怡', '已停用，仅供历史批次追溯参考。');
INSERT INTO clause_doc (id, jurisdiction, doc, doc_version, clause_no, title, body, scope, effective_from, source) VALUES
  ('CL-MO-015', 'MO', '【模拟】澳门AMCM资本充足率指引', '2026版', '第15条', '主权及中央银行风险暴露', '【模拟条款原文】对澳门特别行政区政府及中央银行的风险暴露，风险权重为 0%。对其他主权国家或经济实体的风险暴露，按其外部信用评级确定风险权重。', '所有产品的对主权及中央银行债权', '2026-01-01', '【模拟】AMCM 2026 年第 3 号通告附件'),
  ('CL-MO-016', 'MO', '【模拟】澳门AMCM资本充足率指引', '2026版', '第16条', '公共部门实体风险暴露', '【模拟条款原文】对境内公共部门实体的债权，风险权重为 50%；对境外公共部门实体的债权，风险权重为 100%，另有规定的从其规定。', '所有产品的对公共部门实体债权', '2026-01-01', '【模拟】AMCM 2026 年第 3 号通告附件'),
  ('CL-MO-018', 'MO', '【模拟】澳门AMCM资本充足率指引', '2026版', '第18条', '多边开发银行风险暴露', '【模拟条款原文】对合格多边开发银行的债权，风险权重为 0%。合格名单由监管机构另行公布，并在名单更新时同步维护。', '所有产品的对多边开发银行债权', '2026-01-01', '【模拟】AMCM 2026 年第 3 号通告附件'),
  ('CL-MO-022', 'MO', '【模拟】澳门AMCM资本充足率指引', '2026版', '第22条', '商业银行风险暴露', '【模拟条款原文】对商业银行的债权，按是否满足最低资本要求、其他各级资本要求及外部审计意见划分为 A+、A、B、C 四档；C 档风险权重为 150%。原始期限三个月以内，或跨境货物贸易且原始期限不超过六个月的，适用短期风险权重。', '所有产品的对商业银行债权', '2026-01-01', '【模拟】AMCM 2026 年第 3 号通告附件'),
  ('CL-MO-030', 'MO', '【模拟】澳门AMCM资本充足率指引', '2026版', '第30条', '居住用房地产风险暴露', '【模拟条款原文】以居住用房地产设定抵押、且还款不实质依赖该房地产现金流的债权，按贷款价值比分档确定风险权重，比例越低权重越低。商住两用房地产归入商用房地产处理。', '对公贷款、个人贷款的房地产抵押类债权', '2026-01-01', '【模拟】AMCM 2026 年第 3 号通告附件'),
  ('CL-MO-031', 'MO', '【模拟】澳门AMCM资本充足率指引', '2026版', '第31条', '商用房地产风险暴露', '【模拟条款原文】以商用房地产设定抵押的债权，区分还款是否实质依赖该房地产现金流。实质依赖且贷款价值比高于 60% 但不超过 80% 的，风险权重取 90% 与该交易对手普通债权风险权重的较大者。', '对公贷款、个人贷款的商用房地产抵押类债权', '2026-01-01', '【模拟】AMCM 2026 年第 3 号通告附件'),
  ('CL-MO-036', 'MO', '【模拟】澳门AMCM资本充足率指引', '2026版', '第36条', '已违约风险暴露', '【模拟条款原文】债务人逾期超过 90 天，或不处置抵押品就可能无法全额偿还的，认定为已违约。损失准备占账面价值比例不低于 20% 的，风险权重为 100%；低于 20% 的，风险权重为 150%。', '所有产品', '2026-01-01', '【模拟】AMCM 2026 年第 3 号通告附件'),
  ('CL-MO-042', 'MO', '【模拟】澳门AMCM资本充足率指引', '2026版', '第42条', '监管零售风险暴露', '【模拟条款原文】对单一自然人或小微企业的债权，对单一债务人风险暴露不超过 1000 万元，且占全行信用风险暴露比例不超过 0.5% 的，认定为监管零售风险暴露，风险权重为 75%。', '个人贷款、小微企业贷款', '2026-01-01', '【模拟】AMCM 2026 年第 3 号通告附件'),
  ('CL-MO-045', 'MO', '【模拟】澳门AMCM资本充足率指引', '2026版', '第45条', '公司风险暴露', '【模拟条款原文】公司风险暴露中，符合中小企业划型标准、最近一年营业收入不超过 3 亿元、对单一债务人风险暴露不超过 1000 万元的，适用中小企业权重。同时满足十项投资级认定条件的，适用投资级公司权重。', '对公贷款、债券投资', '2026-01-01', '【模拟】AMCM 2026 年第 3 号通告附件'),
  ('CL-MO-050', 'MO', '【模拟】澳门AMCM资本充足率指引', '2026版', '第50条', '资产担保债券', '【模拟条款原文】同时满足资产池仅含合格资产、资产池名义价值与未偿还债券名义价值之比不低于 110%、至少每半年可取得披露信息三项条件的，为合格资产担保债券。不合格的，按交易对手普通债权确定权重。', '债券投资', '2026-01-01', '【模拟】AMCM 2026 年第 3 号通告附件'),
  ('CL-MO-060', 'MO', '【模拟】澳门AMCM资本充足率指引', '2026版', '第60条', '表内风险暴露 EAD', '【模拟条款原文】表内风险暴露的违约风险暴露等于账面余额扣除已计提的损失准备后的金额。', '所有表内业务', '2026-01-01', '【模拟】AMCM 2026 年第 3 号通告附件'),
  ('CL-MO-064', 'MO', '【模拟】澳门AMCM资本充足率指引', '2026版', '第64条', '表外风险暴露 EAD', '【模拟条款原文】表外项目的违约风险暴露等于表外余额乘以相应的信用转换系数，再加上已计入表内的部分。不同业务品种的信用转换系数按其性质确定。', '表外授信及承诺', '2026-01-01', '【模拟】AMCM 2026 年第 3 号通告附件'),
  ('CL-CN-015', 'CN', '【模拟】商业银行资本管理办法', '2026版', '第十五条', '风险暴露分类与权重', '【模拟条款原文】商业银行应按本办法规定的分类标准划分信用风险暴露，并按对应的风险权重计量风险加权资产。', '全部信用风险暴露', '2026-01-01', '【模拟】附件2 权重法风险权重表'),
  ('CL-HK-020', 'HK', '【模拟】香港银行业（资本）规则', '2025版', '第20条', '监管零售组合', '【模拟条款原文】符合监管零售组合认定标准的风险暴露，风险权重为 75%。', '个人贷款、中小企业贷款', '2025-07-01', '【模拟】香港金管局规则附件');
