INSERT INTO product_field (product_code, code, name, meaning, data_type, unit, required, source_system, source_field, transform_rule, validate_rule, options_json, referenced_json, std_field) VALUES
  ('corp_loan', 'bal', '债项余额', '这笔债项的账面本金余额，已折算为计量币种，不含利息。', 'number', '元', 1, 'CL-D-101', 'LOAN_BAL', '数值转换（去千分位）', '必须大于 0，且不超过 100 亿元', '[]', '["CL-MO-045"]', 'balance'),
  ('corp_loan', 'cpt', '交易对手类型', '债务人的主体性质，决定进入哪一条主体分支。', 'enum', '', 1, 'CL-D-101', 'CPTY_TYPE', '枚举映射：C→公司，P→自然人，B→商业银行', '必须在枚举范围内', '["公司","自然人","商业银行","其他金融机构","公共部门实体","特殊目的实体"]', '["CL-MO-022","CL-MO-042","CL-MO-045"]', 'counterparty_type'),
  ('corp_loan', 'ccy', '币种', '债项原币种，需按基准日汇率折算为计量币种。', 'enum', '', 1, 'CL-D-101', 'CCY', '字典映射 + 汇率折算', '必须为有效 ISO 币种', '["MOP","CNY","HKD","USD"]', '[]', NULL),
  ('corp_loan', 'mat', '剩余期限', '自计量基准日至到期日的月数，不是原始期限。', 'number', '月', 1, 'CL-D-101', 'MATURITY_DATE', '（到期日 − 基准日）/ 30，向上取整', '必须大于 0', '[]', '["CL-MO-022"]', 'remaining_maturity_months'),
  ('corp_loan', 'grnt', '担保方式', '本笔贷款的主要担保方式，决定是否需要判断房地产抵押。', 'enum', '', 1, 'CL-D-101', 'GUARANTEE_TYPE', '字典映射', '必须在枚举范围内', '["信用","保证","抵押","质押"]', '["CL-MO-030","CL-MO-031"]', 'has_property_collateral'),
  ('corp_loan', 'coll', '抵质押品类型', '押品的具体类型，用于判断是否为房地产及其用途。', 'enum', '', 0, '抵押品詳情表', 'Collateral Type1', '字典映射', '抵押方式下必填', '["居住用房","商用房","商住两用","厂房","存单","股权"]', '["CL-MO-030","CL-MO-031"]', 'property_uses'),
  ('corp_loan', 'ltv', '贷款价值比', '债项余额 / 押品评估价值。50% 记作 0.5。', 'number', '比值', 0, '计算字段', '—', '债项余额 ÷ 押品评估价值（MOP）', '0 < 值 ≤ 2', '[]', '["CL-MO-030","CL-MO-031"]', 'ltv'),
  ('corp_loan', 'eval', '交易对手评级', '外部评级机构给出的债务人评级，用于投资级判断。', 'enum', '', 0, '同業rating', 'RATING', '评级映射（S&P 口径）', '必须在评级枚举内', '["AAA","AA","A","BBB","BB","B","未评级"]', '[]', 'issuer_rating'),
  ('corp_loan', 'size', '企业划型', '按国家划型标准确定的企业规模，影响中小企业认定。', 'enum', '', 0, '本地中小企', 'SIZE_TYPE', '字典映射', '必须在枚举范围内', '["大型","中型","小型","微型"]', '["CL-MO-045"]', 'enterprise_size'),
