INSERT INTO exposure_document (id, name, title, source_file, body) VALUES (1, 'cn_sa_exposure_class', '风险暴露分类', 'agent/subagents/weight/knowledge/权重法风险暴露分类.json', '{"name":"cn_sa_exposure_class","title":"风险暴露分类","fields":[{"name":"instrument_type","label":"工具","meaning":"这一笔是现金、黄金、其他资产、股权、资产担保债券，还是普通债权。表头可能叫业务品种、资产类型。单元格原文要在映射里对到 cash、gold、other_asset、equity、covered_bond、claim。库存现金和黄金不是债权。固定资产、无形资产、递延费用没有交易对手，填 other_asset。存放中央银行仍填 claim，再按交易对手走主权。","source":"column","type":"enum","options":[{"label":"现金","code":"cash"},{"label":"黄金","code":"gold"},{"label":"其他资产","code":"other_asset"},{"label":"股权","code":"equity"},{"label":"资产担保债券","code":"covered_bond"},{"label":"债权","code":"claim"}]},{"name":"treat_as_equity","label":"是否应视同股权","meaning":"债权是否应视同股权。收益主要靠资本利得、不可赎回、有剩余索取权，或与一级资本同样结构，或约定用股票清偿。监管已认可按债务处理的为 no。","source":"column","type":"enum","note":"收益主要靠资本利得、不可赎回、有剩余索取权，或与一级资本同样结构，或约定用股票清偿。监管已认可按债务处理的填 no。","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"state_subsidized_equity","label":"是否国家重大补贴并受政府监督的股权","meaning":"是否获得国家重大补贴并受到政府监督的股权。中央财政持股，方案写明规模、范围、运作和风险，并经国务院批准。","source":"column","type":"enum","note":"中央财政持股，方案写明规模、范围、运作和风险，并经国务院批准。","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"is_defaulted","label":"是否已违约","meaning":"是否已违约：逾期超过 90 天，或不处置押品就可能无法全额偿还。自然人按这一笔，其他按这个债务人。表里若是逾期天数或五级分类，在映射的 how 里写成 yes 或 no。","source":"column","type":"enum","note":"逾期超过 90 天，或不处置押品就可能无法全额偿还。自然人按债项填，其他按债务人填。","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"is_subordinated","label":"是否次级债权","meaning":"是否次级债权，受偿顺序在普通债权之后。金融机构风险暴露不含次级债权。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"covered_pool_eligible","label":"资产池是否只含合格资产","meaning":"资产担保债券的资产池是否只含合格资产。合格范围是附件2第十部分列出的那几类。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"covered_oc_ratio","label":"资产池名义价值 / 未偿还债券名义价值","meaning":"资产池名义价值除以未偿还债券名义价值。110% 写成 1.1。可以是一列比率，也可以由资产池名义价值和债券名义价值两列相除。","source":"column","type":"number","unit":"ratio","note":"110% 写成 1.1。"},{"name":"covered_disclosure_ok","label":"是否至少每半年能取得披露信息","meaning":"是否至少每半年能取得资产池和债券的披露信息。披露内容见附件2第十部分。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"counterparty_type","label":"交易对手","meaning":"债务人属于哪一类主体。财政部对 cn_central_government，人民银行对 cn_central_bank。农村合作银行、村镇银行、农村信用合作社对 commercial_bank。表头可能叫客户类型、发行人类型。","source":"column","type":"enum","extensible":true,"note":"财政部填 cn_central_government，人民银行填 cn_central_bank。农村合作银行、村镇银行、农村信用合作社填 commercial_bank。要加新种类，在 options 加一项，规则里的 match 写它的 code。","options":[{"label":"我国中央政府","code":"cn_central_government"},{"label":"我国中央银行","code":"cn_central_bank"},{"label":"其他主权国家或经济实体","code":"foreign_sovereign"},{"label":"其他中央银行","code":"foreign_central_bank"},{"label":"国际清算银行","code":"bis"},{"label":"国际货币基金组织","code":"imf"},{"label":"欧洲中央银行","code":"ecb"},{"label":"欧盟","code":"eu"},{"label":"欧洲稳定机制","code":"esm"},{"label":"欧洲金融稳定机制","code":"efsm"},{"label":"公共部门实体","code":"pse"},{"label":"多边开发银行","code":"mdb"},{"label":"商业银行","code":"commercial_bank"},{"label":"其他金融机构","code":"other_fi"},{"label":"开发性金融机构","code":"development_fi"},{"label":"政策性银行","code":"policy_bank"},{"label":"公司","code":"corporate"},{"label":"合伙制企业","code":"partnership"},{"label":"独资企业","code":"sole_proprietorship"},{"label":"特殊目的实体","code":"spe"},{"label":"其他非自然人","code":"other_non_individual"},{"label":"自然人","code":"individual"}]},{"name":"counterparty_name","label":"交易对手名称","meaning":"交易对手的法定名称。合格多边开发银行要和规则 mdb_qualified 里的名称逐字相同。","source":"column","type":"string","note":"合格多边开发银行在规则 mdb_qualified 里按这个名称核对。"},{"name":"fi_subtype","label":"其他金融机构类型","meaning":"其他金融机构的具体种类，仅当交易对手是其他金融机构时需要。对 options 里的中文，例如证券公司、企业集团财务公司。","source":"column","type":"enum","extensible":true,"options":[{"label":"证券公司","code":"securities"},{"label":"保险公司","code":"insurer"},{"label":"保险资产管理公司","code":"insurance_amc"},{"label":"金融资产管理公司","code":"amc"},{"label":"信托公司","code":"trust"},{"label":"企业集团财务公司","code":"group_finance_company"},{"label":"金融租赁公司","code":"financial_leasing"},{"label":"汽车金融公司","code":"auto_finance"},{"label":"货币经纪公司","code":"money_broker"},{"label":"消费金融公司","code":"consumer_finance"},{"label":"基金公司","code":"fund"},{"label":"理财公司","code":"wealth"},{"label":"金融资产投资公司","code":"investment_company"},{"label":"金融控股公司","code":"financial_holding"},{"label":"其他受金融监管部门监管的机构","code":"other_regulated"}]},{"name":"pse_region","label":"公共部门所在地","meaning":"公共部门实体在境内还是境外。境内为 domestic，境外为 overseas。","source":"column","type":"enum","options":[{"label":"境内","code":"domestic"},{"label":"境外","code":"overseas"}]},{"name":"pse_claim","label":"对公共部门的债权种类","meaning":"对公共部门这笔债权的种类。金融资产管理公司为收购国有银行不良贷款而定向发行的债券为 amc_bond；省、自治区、直辖市及计划单列市人民政府债券为 local_gov_bond；其余为 other。","source":"column","type":"enum","options":[{"label":"金融资产管理公司为收购国有银行不良贷款而定向发行的债券","code":"amc_bond"},{"label":"省（自治区、直辖市）及计划单列市人民政府债券","code":"local_gov_bond"},{"label":"其他","code":"other"}]},{"name":"gov_bond_type","label":"政府债券类型","meaning":"政府债券是一般债券还是专项债券。只在债权种类是政府债券时需要。一般债券为 general，专项债券为 special。","source":"column","type":"enum","options":[{"label":"一般债券","code":"general"},{"label":"专项债券","code":"special"}]},{"name":"revenue_mainly_central","label":"收入是否主要源于中央财政","meaning":"这个公共部门的收入是否主要源于中央财政。不包括财政部和人民银行。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"meets_minimum_capital","label":"是否满足最低资本要求","meaning":"作为交易对手的那家商业银行是否满足最低资本要求，不含第二支柱。是 yes，否 no，无法判断 unknown。这不是本行自己的资本。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"},{"label":"无法判断","code":"unknown"}]},{"name":"meets_other_capital","label":"是否满足其他各级资本要求","meaning":"作为交易对手的商业银行是否满足储备资本、逆周期资本、系统重要性附加资本。无法判断时不要映射成 yes 或 no，留给人工字段 manual_bank_grade。","source":"column","type":"enum","note":"储备资本、逆周期资本、系统重要性附加资本。不含第二支柱。","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"},{"label":"无法判断","code":"unknown"}]},{"name":"cet1_ratio","label":"核心一级资本充足率","meaning":"作为交易对手的商业银行的核心一级资本充足率。14% 写成 0.14。","source":"column","type":"number","unit":"ratio","note":"14% 写成 0.14。"},{"name":"leverage_ratio","label":"杠杆率","meaning":"作为交易对手的商业银行的杠杆率。5% 写成 0.05。","source":"column","type":"number","unit":"ratio","note":"5% 写成 0.05。"},{"name":"audit_opinion","label":"外部审计意见","meaning":"作为交易对手的商业银行的外部审计意见。无报告 none，无保留 unqualified，保留 qualified，否定 adverse，无法表示 disclaimer，持续经营存疑 going_concern。","source":"column","type":"enum","options":[{"label":"无报告","code":"none"},{"label":"无保留","code":"unqualified"},{"label":"保留","code":"qualified"},{"label":"否定","code":"adverse"},{"label":"无法表示","code":"disclaimer"},{"label":"持续经营存疑","code":"going_concern"}]},{"name":"loan_purpose","label":"融资用途","meaning":"这笔融资的用途。地产开发、房屋建设、项目建设、购买实物资产、商品融资或其他，对到 land_development、housing_construction、project、object_purchase、commodity、other。","source":"column","type":"enum","extensible":true,"options":[{"label":"地产开发","code":"land_development"},{"label":"房屋建设","code":"housing_construction"},{"label":"项目建设","code":"project"},{"label":"购买实物资产","code":"object_purchase"},{"label":"商品融资","code":"commodity"},{"label":"其他","code":"other"}]},{"name":"spe_for_physical_asset","label":"是否为实物资产设立的特殊目的实体","meaning":"债务人是否为某一实物资产设立的特殊目的实体。判断专业贷款的三个特征之一。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"no_independent_repayment","label":"除资产收入外没有独立还款能力","meaning":"除该资产产生的收入外，债务人是否没有独立还款能力。判断专业贷款的三个特征之二。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"lender_controls_asset","label":"银行对资产及其收入有相当控制权","meaning":"银行对资产及其收入是否有相当控制权。判断专业贷款的三个特征之三。三条同时为 yes 才是专业贷款。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"project_company","label":"是否为该项目组建","meaning":"债务人是否为该项目组建。只有项目融资还要看这一项。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"repayment_from_project","label":"还款是否主要靠项目自身收入","meaning":"还款是否主要靠项目自身收入。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"project_cashflow_covers_debt","label":"项目现金流是否足以偿还剩余债务","meaning":"项目现金流是否足以偿还剩余债务。这是运营阶段项目融资的条件之一。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"long_term_debt_declining","label":"长期负债是否在减少","meaning":"长期负债是否在减少。这是运营阶段项目融资的条件之二。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"repayment_from_lease","label":"还款是否主要靠该资产出租","meaning":"还款是否主要靠该实物资产出租，例如船舶、飞机、轨道交通工具。这是物品融资。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"repayment_from_commodity_sale","label":"没有其他资产且还款靠出售商品","meaning":"债务人是否没有其他资产，且还款靠出售商品。这是商品融资。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"has_property_collateral","label":"是否有房地产抵押","meaning":"这笔是否有房地产抵押。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"property_uses","label":"抵押物用途","meaning":"抵押房地产的用途，可以多选。居住 residential，商用 commercial，商住两用 mixed_use。表里若是一个文本列，把原文对到 code。","source":"column","type":"list","options":[{"label":"居住","code":"residential"},{"label":"商用","code":"commercial"},{"label":"商住两用","code":"mixed_use"}]},{"name":"single_exposure","label":"对单一债务人的风险暴露","meaning":"对同一债务人的风险暴露金额，单位元。企业按单家或集团，个人按该自然人。1000 万写成 10000000。已经是一列就直接映射；要按债务人把多行加总时，在 how 里写。","source":"column","type":"number","unit":"CNY","note":"企业按单家或集团，个人按该自然人。1000 万写成 10000000。"},{"name":"exposure_share","label":"占全行信用风险暴露的比例","meaning":"该债务人风险暴露占全行信用风险暴露的比例。0.5% 写成 0.005。用该债务人金额除以全表信用风险暴露合计，不要找一列现成的占比，除非表里已经算好。","source":"calc","type":"number","unit":"ratio","note":"0.5% 写成 0.005。"},{"name":"enterprise_size","label":"企业划型","meaning":"按国家划型标准确定的企业规模。微型 micro，小型 small，中型 medium，大型 large。","source":"column","type":"enum","options":[{"label":"微型","code":"micro"},{"label":"小型","code":"small"},{"label":"中型","code":"medium"},{"label":"大型","code":"large"}]},{"name":"revenue_last_year","label":"最近一年营业收入","meaning":"最近一年营业收入，单位元。3 亿写成 300000000。","source":"column","type":"number","unit":"CNY","note":"3 亿写成 300000000。"},{"name":"operating_normal","label":"经营正常且按时披露","meaning":"是否经营正常、没有风险迹象，并且按时披露财务报告。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"no_major_violation_3y","label":"最近三年无重大违法违规","meaning":"最近三年是否没有重大违法违规。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"not_on_dishonest_list","label":"未进失信名单","meaning":"是否未纳入人民法院失信被执行人名单。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"no_false_statements","label":"财报没有虚假记载","meaning":"财务报表是否没有虚假记载。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"annual_audit_opinion","label":"最新年报审计意见","meaning":"该公司或该机构最新年报的审计意见。投资级要求无保留 unqualified。这和商业银行评级用的 audit_opinion 不是同一列。","source":"column","type":"enum","options":[{"label":"无保留","code":"unqualified"},{"label":"保留","code":"qualified"},{"label":"否定","code":"adverse"},{"label":"无法表示","code":"disclaimer"},{"label":"无报告","code":"none"}]},{"name":"no_default_3y","label":"最近三年没有违约或拖欠","meaning":"最近三年是否没有违约或拖欠。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"loan_classification_normal","label":"本行分类均为正常","meaning":"本行对这个债务人的债权，风险分类是否都是正常。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"has_listed_security","label":"有存续的股票或债券","meaning":"是否在认可的交易所或银行间市场有存续的股票或债券。资产证券化不算。","source":"column","type":"enum","note":"认可的交易所或银行间市场。资产证券化不算。","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"guarantee_reasonable","label":"对外担保规模合理","meaning":"对外担保规模是否合理。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"profit_tests_met","label":"盈利条件都满足","meaning":"盈利条件是否都满足：近三年合并利润总额和归属母公司净利润都大于 3000 万；法人利润总额和净利润都大于 0；最新一期两边净利润都大于 0；综合收益都大于 0。由这些财务列判断，在 how 里写，不要找一列叫盈利条件。","source":"calc","type":"enum","note":"近三年合并利润总额和归属母公司净利润都大于 3000 万；法人利润总额和净利润都大于 0；最新一期两边净利润都大于 0；综合收益都大于 0。","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"debt_ratio","label":"上一会计年度末资产负债率","meaning":"上一会计年度末资产负债率。70% 写成 0.7。可以是一列，也可以由总负债和总资产相除。","source":"column","type":"number","unit":"ratio","note":"70% 写成 0.7。"},{"name":"financial_industry","label":"是否金融行业","meaning":"债务人是否属于金融行业。为 yes 时，投资级可以不要求经营现金流大于财务费用。","source":"column","type":"enum","note":"金融行业可以不要求经营现金流大于财务费用。","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"operating_cashflow_gt_finance_cost","label":"经营现金流大于财务费用","meaning":"上一会计年度经营活动现金流量净额是否大于财务费用。可以是一列是否，也可以由这两列比较。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"financials_updated_within_6m","label":"财务数据在报表日后 6 个月内已更新","meaning":"财务数据在报表日后 6 个月内是否已经更新。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"no_other_material_risk","label":"没有其他重大风险","meaning":"银行是否认为不存在其他重大风险。存在时填 no。表里没有对应列就不要映射，留给人工填。","source":"manual","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"is_credit_card","label":"是否信用卡","meaning":"这笔是不是信用卡。合格交易者只针对信用卡。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"transactor_clean","label":"合格交易者还款记录是否达标","meaning":"合格交易者的还款记录是否达标：过去三年内最近 12 个有欠款的账单周期，都在到期日当天或之前还清。一般由账单历史计算。","source":"calc","type":"enum","note":"过去三年内最近 12 个有欠款的账单周期，均在到期日（含）前全额偿还。","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"bank_tier","label":"银行档次","meaning":"计算这笔的本行是第一档还是第二档。这是本行参数，全表相同，不是客户身上的列。不要按每一行去对。","source":"manual","type":"enum","options":[{"code":"tier1","label":"第一档"},{"code":"tier2","label":"第二档"}]},{"name":"original_maturity_months","label":"原始期限","meaning":"这笔的原始期限，单位月。表里是月数就直接映射；表里是起息日和到期日时，在 how 里换成月数。","source":"column","type":"number","unit":"month"},{"name":"cross_border_trade","label":"是否跨境货物贸易","meaning":"这笔是不是跨境货物贸易。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"issuer_rating","label":"外部评级","meaning":"外部评级符号，如 AAA、AA-、B-，没有评级时用 unrated。只用于境外主权、其他中央银行、其他多边开发银行。不要填债券自己的评级，也不要填注册地评级。","source":"column","type":"enum","extensible":true,"options":[{"code":"AAA","label":"AAA"},{"code":"AA+","label":"AA+"},{"code":"AA","label":"AA"},{"code":"AA-","label":"AA-"},{"code":"A+","label":"A+"},{"code":"A","label":"A"},{"code":"A-","label":"A-"},{"code":"BBB+","label":"BBB+"},{"code":"BBB","label":"BBB"},{"code":"BBB-","label":"BBB-"},{"code":"BB+","label":"BB+"},{"code":"BB","label":"BB"},{"code":"BB-","label":"BB-"},{"code":"B+","label":"B+"},{"code":"B","label":"B"},{"code":"B-","label":"B-"},{"code":"CCC","label":"CCC"},{"code":"CC","label":"CC"},{"code":"C","label":"C"},{"code":"D","label":"D"},{"code":"unrated","label":"unrated"}],"note":"境外主权、其他中央银行、其他多边开发银行使用。合格资产担保债券用自己的 bond_rating，境外公共部门用 country_rating。"},{"name":"cashflow_dependent","label":"还款是否实质依赖房地产现金流","meaning":"还款是否实质依赖房地产产生的现金流。来自该房地产出售或租赁的现金流超过还款来源的 50% 为 yes。可以是一列是否，也可以由房地产现金流和还款来源比较。","source":"column","type":"enum","note":"来自该房地产出售或租赁的现金流超过 50% 填 yes。","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"ltv","label":"贷款价值比","meaning":"贷款余额占抵押房地产价值的比例。50% 写成 0.5。可以是一列贷款价值比，也可以由贷款余额和押品价值相除。","source":"column","type":"number","unit":"ratio","note":"50% 写成 0.5。"},{"name":"prudent","label":"是否符合审慎要求","meaning":"这一笔是否符合该类的审慎要求。房地产开发、居住用房地产、商用房地产的要求不同。表里通常没有现成的一列，没有就不要映射。","source":"manual","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"provision_ratio","label":"损失准备占账面价值的比例","meaning":"损失准备占账面价值的比例，已违约时使用。20% 写成 0.2。可以是一列，也可以由损失准备和账面价值相除。","source":"column","type":"number","unit":"ratio","note":"20% 写成 0.2。"}],"rules":[{"name":"cash","label":"现金及现金等价物","note":"《商业银行资本管理办法》第五十七条。存放中央银行不在本条，按主权风险暴露划分。","when":{"all":[{"field":"instrument_type","op":"in","match":["cash","gold"]}]},"children":[{"name":"cash_on_hand","label":"现金","when":{"all":[{"field":"instrument_type","op":"eq","match":"cash"}]},"value":0},{"name":"gold","label":"黄金","when":{"all":[{"field":"instrument_type","op":"eq","match":"gold"}]},"value":0}]},{"name":"equity","label":"股权风险暴露","note":"已违约的股权仍归本类。","when":{"any":[{"field":"instrument_type","op":"eq","match":"equity"},{"field":"treat_as_equity","op":"eq","match":"yes"}]},"children":[{"fields":[],"name":"equity_subsidized","label":"获得国家重大补贴，并受到政府监督的股权投资","when":{"all":[{"field":"state_subsidized_equity","op":"eq","match":"yes"}]},"note":"《商业银行资本管理办法》第七十六条，风险权重为 250%。","value":2.5},{"name":"equity_fi","label":"金融机构股权投资","note":"未扣除部分。","when":{"all":[{"field":"counterparty_type","op":"in","match":["commercial_bank","other_fi","development_fi","policy_bank"]}]},"value":2.5}],"otherwise":{"name":"equity_corporate","label":"其他工商企业股权投资","value":12.5}},{"name":"defaulted","label":"已违约风险暴露","when":{"all":[{"field":"is_defaulted","op":"eq","match":"yes"}]},"children":[{"name":"defaulted_residential","label":"以居住用房为抵押且不依赖房地产现金流","when":{"all":[{"field":"has_property_collateral","op":"eq","match":"yes"},{"field":"property_uses","op":"contains","match":"residential"},{"field":"cashflow_dependent","op":"eq","match":"no"}]},"value":1}],"otherwise":{"name":"defaulted_other","label":"其他已违约风险暴露","children":[{"name":"defaulted_tier2","label":"第二档银行","when":{"all":[{"field":"bank_tier","op":"eq","match":"tier2"}]},"weight":{"same_as":"counterparty_ordinary_claim"},"note":"《商业银行资本管理办法》第八十条，第二档不单独划分已违约风险暴露，按照交易对手风险权重计量。"},{"name":"defaulted_provision_low","label":"损失准备低于账面价值20%","when":{"all":[{"field":"provision_ratio","op":"lt","match":0.2}]},"value":1.5},{"name":"defaulted_provision_high","label":"损失准备不低于账面价值20%","when":{"all":[{"field":"provision_ratio","op":"gte","match":0.2}]},"value":1}]}},{"name":"covered_bond","label":"合格资产担保债券风险暴露","note":"未满足合格条件时本条不命中，继续按交易对手划分。《商业银行资本管理办法》第七十九条。","when":{"all":[{"field":"instrument_type","op":"eq","match":"covered_bond"},{"field":"covered_pool_eligible","op":"eq","match":"yes"},{"field":"covered_oc_ratio","op":"gte","match":1.1},{"field":"covered_disclosure_ok","op":"eq","match":"yes"}]},"fields":[{"name":"bond_has_rating","label":"债券自身是否有外部信用评级","meaning":"这只资产担保债券自身有没有外部信用评级。表里已有是否评级就映射那一列；若只有评级符号，有符号为 yes，空白为 no。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"bond_rating","label":"债券自身外部信用评级","meaning":"这只资产担保债券自身的外部信用评级符号。不要填发行银行的评级。","source":"column","type":"enum","extensible":true,"note":"只在债券自身有评级时填写。","options":[{"code":"AAA","label":"AAA"},{"code":"AA+","label":"AA+"},{"code":"AA","label":"AA"},{"code":"AA-","label":"AA-"},{"code":"A+","label":"A+"},{"code":"A","label":"A"},{"code":"A-","label":"A-"},{"code":"BBB+","label":"BBB+"},{"code":"BBB","label":"BBB"},{"code":"BBB-","label":"BBB-"},{"code":"BB+","label":"BB+"},{"code":"BB","label":"BB"},{"code":"BB-","label":"BB-"},{"code":"B+","label":"B+"},{"code":"B","label":"B"},{"code":"B-","label":"B-"},{"code":"CCC","label":"CCC"},{"code":"CC","label":"CC"},{"code":"C","label":"C"},{"code":"D","label":"D"},{"code":"unrated","label":"unrated"}]},{"name":"issuer_scra_grade","label":"发行银行的标准信用风险评估结果","meaning":"发行银行的标准信用风险评估结果，只取 A+、A、B、C，对应 a_plus、a、b、c。表里已有级别就映射；没有就留空。","source":"column","type":"enum","note":"债券自身没有评级时，按发行银行的 A+、A、B、C 填写。","options":[{"label":"A+级","code":"a_plus"},{"label":"A级","code":"a"},{"label":"B级","code":"b"},{"label":"C级","code":"c"}]}],"children":[{"name":"covered_bond_tier2","label":"第二档银行","when":{"all":[{"field":"bank_tier","op":"eq","match":"tier2"}]},"weight":{"same_as":"counterparty_ordinary_claim"},"note":"《商业银行资本管理办法》第七十九条，第二档不单独划分合格资产担保债券，按照交易对手风险权重计量。"},{"name":"covered_bond_rated","label":"债券自身具有外部信用评级","when":{"all":[{"field":"bond_has_rating","op":"eq","match":"yes"}]},"children":[{"name":"covered_bond_aa","label":"AA-（含）以上","when":{"all":[{"field":"bond_rating","op":"in","match":["AAA","AA+","AA","AA-"]}]},"value":0.1},{"name":"covered_bond_bbb","label":"AA-以下、BBB-（含）以上","when":{"all":[{"field":"bond_rating","op":"in","match":["A+","A","A-","BBB+","BBB","BBB-"]}]},"value":0.2},{"name":"covered_bond_b","label":"BBB-以下、B-（含）以上","when":{"all":[{"field":"bond_rating","op":"in","match":["BB+","BB","BB-","B+","B","B-"]}]},"value":0.5},{"name":"covered_bond_below_b","label":"B-以下","when":{"all":[{"field":"bond_rating","op":"in","match":["CCC","CC","C","D"]}]},"value":1}]}],"otherwise":{"name":"covered_bond_unrated","label":"债券自身不具有外部信用评级","children":[{"name":"covered_bond_issuer_a_plus","label":"发行银行为A+级","when":{"all":[{"field":"issuer_scra_grade","op":"eq","match":"a_plus"}]},"value":0.15},{"name":"covered_bond_issuer_a","label":"发行银行为A级","when":{"all":[{"field":"issuer_scra_grade","op":"eq","match":"a"}]},"value":0.2},{"name":"covered_bond_issuer_b","label":"发行银行为B级","when":{"all":[{"field":"issuer_scra_grade","op":"eq","match":"b"}]},"value":0.35},{"name":"covered_bond_issuer_c","label":"发行银行为C级","when":{"all":[{"field":"issuer_scra_grade","op":"eq","match":"c"}]},"value":1}]}},{"name":"subordinated","label":"次级债权","note":"附件未单列。先单独成类，避免进入金融机构或一般公司。","when":{"all":[{"field":"is_subordinated","op":"eq","match":"yes"}]},"children":[{"name":"subordinated_policy","label":"对我国开发性金融机构和政策性银行的次级债权","note":"未扣除部分。","when":{"all":[{"field":"counterparty_type","op":"in","match":["development_fi","policy_bank"]}]},"value":1}],"otherwise":{"name":"subordinated_other","label":"其他次级债权及TLAC工具","note":"含 TLAC 工具。","value":1.5}},{"name":"sovereign","label":"主权风险暴露（主权国家/央行/国际组织）","when":{"all":[{"field":"counterparty_type","op":"in","match":["cn_central_government","cn_central_bank","foreign_sovereign","foreign_central_bank","bis","imf","ecb","eu","esm","efsm"]}]},"children":[{"name":"sovereign_cn","label":"对我国中央政府、央行的债权","when":{"all":[{"field":"counterparty_type","op":"in","match":["cn_central_government","cn_central_bank"]}]},"value":0},{"name":"sovereign_intl","label":"国际清算银行、国际货币基金组织、欧洲中央银行、欧盟、欧洲稳定机制和欧洲金融稳定机制","when":{"all":[{"field":"counterparty_type","op":"in","match":["bis","imf","ecb","eu","esm","efsm"]}]},"value":0,"note":"《商业银行资本管理办法》第五十九条。"},{"name":"sovereign_foreign","label":"其他国家或地区政府及其中央银行","when":{"all":[{"field":"counterparty_type","op":"in","match":["foreign_sovereign","foreign_central_bank"]}]},"children":[{"name":"sovereign_foreign_aa","label":"AA-（含）以上","when":{"all":[{"field":"issuer_rating","op":"in","match":["AAA","AA+","AA","AA-"]}]},"value":0},{"name":"sovereign_foreign_a","label":"AA-以下、A-（含）以上","when":{"all":[{"field":"issuer_rating","op":"in","match":["A+","A","A-"]}]},"value":0.2},{"name":"sovereign_foreign_bbb","label":"A-以下、BBB-（含）以上","when":{"all":[{"field":"issuer_rating","op":"in","match":["BBB+","BBB","BBB-"]}]},"value":0.5},{"name":"sovereign_foreign_b","label":"BBB-以下、B-（含）以上","when":{"all":[{"field":"issuer_rating","op":"in","match":["BB+","BB","BB-","B+","B","B-"]}]},"value":1},{"name":"sovereign_foreign_below_b","label":"B-以下","when":{"all":[{"field":"issuer_rating","op":"in","match":["CCC","CC","C","D"]}]},"value":1.5},{"name":"sovereign_foreign_unrated","label":"未评级","when":{"all":[{"field":"issuer_rating","op":"eq","match":"unrated"}]},"value":1}],"note":"《商业银行资本管理办法》第五十八条。"}]},{"name":"pse","label":"公共部门实体风险暴露","when":{"all":[{"field":"counterparty_type","op":"eq","match":"pse"}]},"children":[{"name":"pse_overseas","label":"境外公共部门实体风险暴露","when":{"all":[{"field":"pse_region","op":"eq","match":"overseas"}]},"fields":[{"name":"country_rating","la