eld":"ltv","op":"gt","match":0.8},{"field":"ltv","op":"lte","match":0.9}]},"value":0.4},{"name":"re_residential_indep_100","label":"贷款价值比高于90%、不超过100%","when":{"all":[{"field":"ltv","op":"gt","match":0.9},{"field":"ltv","op":"lte","match":1}]},"value":0.5},{"name":"re_residential_indep_high","label":"贷款价值比超过100%","when":{"all":[{"field":"ltv","op":"gt","match":1}]},"weight":{"same_as":"counterparty_ordinary_claim"},"note":"《商业银行资本管理办法》第七十一条，贷款价值比 100% 以上按照交易对手风险权重计量。"}]},{"name":"re_residential_dependent","label":"实质性依赖房地产所产生的现金流","when":{"all":[{"field":"cashflow_dependent","op":"eq","match":"yes"}]},"children":[{"name":"re_residential_dep_imprudent","label":"不符合审慎要求","when":{"all":[{"field":"prudent","op":"eq","match":"no"}]},"value":1.5,"note":"《商业银行资本管理办法》第七十一条，还款实质性依赖现金流且不符合审慎要求的，风险权重为 150%。"},{"name":"re_residential_dep_low","label":"贷款价值比不超过50%","when":{"all":[{"field":"ltv","op":"lte","match":0.5}]},"value":0.3},{"name":"re_residential_dep_60","label":"贷款价值比高于50%、不超过60%","when":{"all":[{"field":"ltv","op":"gt","match":0.5},{"field":"ltv","op":"lte","match":0.6}]},"value":0.35},{"name":"re_residential_dep_70","label":"贷款价值比高于60%、不超过70%","when":{"all":[{"field":"ltv","op":"gt","match":0.6},{"field":"ltv","op":"lte","match":0.7}]},"value":0.45},{"name":"re_residential_dep_80","label":"贷款价值比高于70%、不超过80%","when":{"all":[{"field":"ltv","op":"gt","match":0.7},{"field":"ltv","op":"lte","match":0.8}]},"value":0.5},{"name":"re_residential_dep_90","label":"贷款价值比高于80%、不超过90%","when":{"all":[{"field":"ltv","op":"gt","match":0.8},{"field":"ltv","op":"lte","match":0.9}]},"value":0.6},{"name":"re_residential_dep_100","label":"贷款价值比高于90%、不超过100%","when":{"all":[{"field":"ltv","op":"gt","match":0.9},{"field":"ltv","op":"lte","match":1}]},"value":0.75},{"name":"re_residential_dep_high","label":"贷款价值比超过100%","when":{"all":[{"field":"ltv","op":"gt","match":1}]},"value":1.05}]}]},{"name":"re_commercial","label":"商用房地产风险暴露","when":{"all":[{"field":"has_property_collateral","op":"eq","match":"yes"},{"any":[{"field":"property_uses","op":"contains","match":"commercial"},{"field":"property_uses","op":"contains","match":"mixed_use"}]}]},"children":[{"name":"re_commercial_tier2","label":"第二档银行的商用房地产风险暴露","when":{"all":[{"field":"bank_tier","op":"eq","match":"tier2"}]},"weight":{"same_as":"counterparty_ordinary_claim"},"note":"《商业银行资本管理办法》第七十二条，第二档不单独划分商用房地产风险暴露，按照交易对手风险权重计量。"},{"name":"re_commercial_independent","label":"不实质性依赖房地产所产生的现金流","when":{"all":[{"field":"cashflow_dependent","op":"eq","match":"no"}]},"children":[{"name":"re_commercial_indep_imprudent","label":"不符合审慎要求","when":{"all":[{"field":"prudent","op":"eq","match":"no"}]},"weight":{"same_as":"counterparty_ordinary_claim"},"note":"《商业银行资本管理办法》第七十二条，还款不实质性依赖现金流且不符合审慎要求的，按照交易对手风险权重计量。"},{"name":"re_commercial_indep_low","label":"不依赖现金流且贷款价值比不超过60%","when":{"all":[{"field":"ltv","op":"lte","match":0.6}]},"value":0.65}],"otherwise":{"name":"re_commercial_indep_rest","label":"不依赖现金流且贷款价值比超过60%","weight":{"same_as":"counterparty_ordinary_claim"},"note":"《商业银行资本管理办法》第七十二条，贷款价值比 60% 以上按照交易对手风险权重计量。"}},{"name":"re_commercial_dependent","label":"实质性依赖房地产所产生的现金流","when":{"all":[{"field":"cashflow_dependent","op":"eq","match":"yes"}]},"children":[{"name":"re_commercial_dep_imprudent","label":"不符合审慎要求","when":{"all":[{"field":"prudent","op":"eq","match":"no"}]},"value":1.5,"note":"《商业银行资本管理办法》第七十二条，还款实质性依赖现金流且不符合审慎要求的，风险权重为 150%。"},{"name":"re_commercial_dep_low","label":"依赖现金流且贷款价值比不超过60%","when":{"all":[{"field":"ltv","op":"lte","match":0.6}]},"value":0.75},{"name":"re_commercial_dep_mid","label":"依赖现金流且贷款价值比高于60%、不超过80%","when":{"all":[{"field":"ltv","op":"gt","match":0.6},{"field":"ltv","op":"lte","match":0.8}]},"weight":{"greater_of":[0.9,{"same_as":"counterparty_ordinary_claim"}]},"note":"《商业银行资本管理办法》第七十二条，取 90% 与交易对手风险权重中的较大值。"},{"name":"re_commercial_dep_high","label":"依赖现金流且贷款价值比超过80%","when":{"all":[{"field":"ltv","op":"gt","match":0.8}]},"value":1.1}]}]},{"name":"retail","label":"个人风险暴露","when":{"all":[{"field":"counterparty_type","op":"eq","match":"individual"}]},"children":[{"name":"retail_regulatory","label":"监管零售个人风险暴露","when":{"all":[{"field":"single_exposure","op":"lte","match":10000000},{"field":"exposure_share","op":"lte","match":0.005}]},"children":[{"name":"retail_transactor","label":"合格交易者个人风险暴露","when":{"all":[{"field":"is_credit_card","op":"eq","match":"yes"},{"field":"transactor_clean","op":"eq","match":"yes"}]},"value":0.45}],"otherwise":{"name":"retail_regulatory_other","label":"其他监管零售个人风险暴露","value":0.75}}],"otherwise":{"name":"retail_other","label":"其他个人风险暴露","value":1}},{"name":"corporate_general","label":"一般公司风险暴露","when":{"all":[{"field":"counterparty_type","op":"in","match":["corporate","partnership","sole_proprietorship","spe","other_non_individual"]}]},"children":[{"name":"corporate_micro","label":"小微企业风险暴露","when":{"all":[{"field":"enterprise_size","op":"in","match":["micro","small"]},{"field":"single_exposure","op":"lte","match":10000000},{"field":"exposure_share","op":"lte","match":0.005}]},"value":0.75},{"name":"corporate_ig","label":"投资级公司风险暴露","when":{"all":[{"field":"operating_normal","op":"eq","match":"yes"},{"field":"no_major_violation_3y","op":"eq","match":"yes"},{"field":"not_on_dishonest_list","op":"eq","match":"yes"},{"field":"no_false_statements","op":"eq","match":"yes"},{"field":"annual_audit_opinion","op":"eq","match":"unqualified"},{"field":"no_default_3y","op":"eq","match":"yes"},{"field":"loan_classification_normal","op":"eq","match":"yes"},{"field":"has_listed_security","op":"eq","match":"yes"},{"field":"guarantee_reasonable","op":"eq","match":"yes"},{"field":"profit_tests_met","op":"eq","match":"yes"},{"field":"debt_ratio","op":"lte","match":0.7},{"any":[{"field":"financial_industry","op":"eq","match":"yes"},{"field":"operating_cashflow_gt_finance_cost","op":"eq","match":"yes"}]},{"field":"financials_updated_within_6m","op":"eq","match":"yes"},{"field":"no_other_material_risk","op":"eq","match":"yes"}]},"children":[{"name":"corporate_ig_tier2","label":"第二档银行不单独划分投资级公司","note":"第二档不单独划分投资级，按一般公司。","when":{"all":[{"field":"bank_tier","op":"eq","match":"tier2"}]},"value":1}],"otherwise":{"name":"corporate_ig_tier1","label":"投资级公司风险暴露","value":0.75},"note":"条件写在本条里，与另一类投资级互不影响。"},{"name":"corporate_sme","label":"中小企业风险暴露","when":{"all":[{"field":"revenue_last_year","op":"lte","match":300000000},{"field":"enterprise_size","op":"in","match":["medium","small","micro"]}]},"value":0.85}],"otherwise":{"name":"corporate_other","label":"其他一般公司风险暴露","value":1}},{"name":"other_asset","label":"其他资产","note":"《商业银行资本管理办法》第八十一条。没有交易对手的表内资产，如固定资产、无形资产和递延费用。","when":{"all":[{"field":"instrument_type","op":"eq","match":"other_asset"}]},"value":1},{"name":"multiple_assessments","label":"多重评级取值","note":"写在规则树里。这一条不判断风险暴露类型，没有 when，分类往下走时不会停在这里，也不会挡住前面的类别。一笔上有多家外部评级时，先按 children 选定用哪个评级的权重，再从现金那一条重新分类。商业银行的 A+、A、B、C 仍由商业银行那一支决定。","applies_to":["issuer_rating","bond_rating","country_rating"],"pick":[{"when":{"field":"assessment_count","op":"eq","match":1},"use":"only"},{"when":{"field":"assessment_count","op":"eq","match":2},"use":"higher_weight"},{"when":{"field":"assessment_count","op":"gte","match":3},"use":"higher_of_two_lowest_weights"}],"children":[{"name":"multiple_assessments_one","label":"只有1个评级","note":"用该评级对应的权重。","when":{"all":[{"field":"assessment_count","op":"eq","match":1}]}},{"name":"multiple_assessments_two","label":"2个评级且权重不同","note":"用较高的风险权重。权重相同就用这个权重。","when":{"all":[{"field":"assessment_count","op":"eq","match":2}]}},{"name":"multiple_assessments_many","label":"3个及以上评级且权重不同","note":"先取权重最低的两个，再用这两个中较高的权重。不得为了降低资本要求改选评级。","when":{"all":[{"field":"assessment_count","op":"gte","match":3}]}}]},{"name":"crm_split","label":"信用风险缓释拆分","note":"写在规则树里。权重分类不进入这一条。原债务人的风险权重在前面的规则里已经确定，这里只拆本金。覆盖金额、未覆盖金额、保护方权重、币种是否相同、抵押品类型缺任何一项时，不拆分。","formula":"covered_amount * protection_weight_used + uncovered_amount * debtor_weight","covered":{"floor":0.2,"note":"未触发 0% 豁免时，被覆盖部分的权重取保护方权重和 0.2 中的较大者。"},"fields":[{"name":"covered_amount","label":"被覆盖金额","meaning":"抵押或担保保护得住的那一部分本金。货币错配时先按抵押品价值折扣后再填。","source":"column","type":"number"},{"name":"uncovered_amount","label":"未覆盖金额","meaning":"没有抵押或担保保护的那一部分本金。","source":"column","type":"number"},{"name":"protection_weight","label":"保护方权重","meaning":"抵押品或担保人自己的风险权重，用比值。20% 写成 0.2。","source":"column","type":"number"},{"name":"debtor_weight","label":"原债务人权重","meaning":"原债务人已经确定的风险权重。拆分时原样使用，不在这里改。","source":"calc","type":"number"},{"name":"same_currency","label":"抵押品与债权是否同币种","meaning":"抵押品币种和债权币种相同填 yes，不同填 no。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]},{"name":"collateral_kind","label":"抵押品类型","meaning":"现金存款、极优质主权债，或其他。","source":"column","type":"enum","options":[{"label":"现金存款","code":"cash_deposit"},{"label":"极优质主权债","code":"sovereign_debt"},{"label":"其他","code":"other"}]},{"name":"sovereign_market_haircut","label":"主权债市值折扣","meaning":"极优质主权债用作抵押时，市值已经按八折计入则填 0.8。不是主权债就不要填。","source":"column","type":"number"}],"children":[{"name":"crm_currency_mismatch","label":"货币错配折扣","note":"抵押品与债权币种不同时，抵押品价值乘 0.5，再用折后价值确定被覆盖金额。","when":{"all":[{"field":"same_currency","op":"eq","match":"no"}]},"collateral_value_factor":0.5},{"name":"crm_zero_exemption","label":"被覆盖部分 0% 豁免","note":"同币种，且抵押品是现金存款或极优质主权债。主权债还要市值已经按 0.8 计入。满足时被覆盖部分权重用 0，不再套 0.2 下限。现金存款不要求这个八折。","when":{"all":[{"field":"same_currency","op":"eq","match":"yes"},{"field":"collateral_kind","op":"in","match":["cash_deposit","sovereign_debt"]}]},"if_collateral_kind":{"match":"sovereign_debt","requires":{"field":"sovereign_market_haircut","op":"eq","match":0.8}},"value":0}]}],"otherwise":{"name":"unclassified","label":"未归类"},"extensions":[{"example":true,"note":"可删除。挂在 fi_other_general 下再拆。","attach_to":"fi_other_general","fields":[{"name":"intra_group","label":"是否集团成员","meaning":"例子。这家企业集团财务公司是不是本集团成员。","source":"column","type":"enum","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]}],"children":[{"name":"fi_intra_group_finance_co","label":"集团内的企业集团财务公司","when":{"all":[{"field":"fi_subtype","op":"eq","match":"group_finance_company"},{"field":"intra_group","op":"eq","match":"yes"}]}},{"name":"fi_extra_group_finance_co","label":"集团外的企业集团财务公司","when":{"all":[{"field":"fi_subtype","op":"eq","match":"group_finance_company"},{"field":"intra_group","op":"eq","match":"no"}]}}]},{"example":true,"note":"可删除。挂在 corporate_general 上，小微、投资级、中小、其他一般公司命中后都可再按产品拆。产品取值在 options 里加。","attach_to":"corporate_general","fields":[{"name":"product_name","label":"产品","meaning":"例子。银行内部的产品名称。新增值先加在 options，再把 Excel 里的产品名对到 code。","source":"column","type":"enum","extensible":true,"options":[{"label":"贸易融资","code":"trade_finance"},{"label":"流动资金贷款","code":"working_capital"},{"label":"银团贷款","code":"syndicated"}]}],"children":[{"name":"product_trade_finance","label":"贸易融资","when":{"all":[{"field":"product_name","op":"eq","match":"trade_finance"}]},"fields":[{"name":"sight_lc","label":"是否即期信用证","meaning":"例子。这笔贸易融资是不是即期信用证。只在贸易融资这一支使用。","source":"column","type":"enum","note":"例子。只在贸易融资这一支使用，流动资金贷款不填这个字段。","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]}],"children":[{"name":"tf_sight_lc","label":"即期信用证","when":{"all":[{"field":"sight_lc","op":"eq","match":"yes"}]}}]},{"name":"product_working_capital","label":"流动资金贷款","when":{"all":[{"field":"product_name","op":"eq","match":"working_capital"}]},"fields":[{"name":"revolving","label":"是否循环额度","meaning":"例子。这笔流动资金贷款是不是循环额度。只在流动资金贷款这一支使用。","source":"column","type":"enum","note":"例子。只在流动资金贷款这一支使用。","options":[{"label":"是","code":"yes"},{"label":"否","code":"no"}]}]}]}],"excel":[{"example":true,"note":"可删除。大模型按这个样子写。field 填字段 name。columns 填 Excel 表头。单元格原文作 values 的键，值必须是该字段的 code。数字字段不写 values。","field":"is_defaulted","columns":["是否违约"],"values":{"是":"yes","否":"no"}},{"example":true,"note":"可删除。一个字段来自多列时，把表头都写进 columns，在 how 里写怎么得到字段值。","field":"ltv","columns":["贷款余额","押品评估价值"],"how":"贷款余额 / 押品评估价值，结果用比值，50% 写成 0.5"}]}');
INSERT INTO rule_param (id, grp, name, value, unit, used_for) VALUES
  ('LTV_RES_50', '居住房地产', 'LTV 分界 50%', '50%', '%', '居住用房地产权重条件引用。不依赖现金流且不超过此值、依赖现金流且不超过此值，各走一条权重。'),
  ('LTV_RES_100', '居住房地产', 'LTV 分界 100%', '100%', '%', '居住用房地产权重条件引用。超过此值时，不依赖现金流改为查交易对手，依赖现金流另有一条固定权重。'),
