  ('MO-CL-005', 'corp_loan', 'corporate_ig', '投资级公司风险暴露', 21, 'MO-SA-2026.1', '十项投资级认定条件同时满足（经营正常、无重大违法、未失信、财报无虚假、审计无保留、三年无违约、分类正常、财务更新及时、资产负债率 ≤ 70%、无其他重大风险）', '公司风险暴露', '投资级公司风险暴露', '75%', 'CL-MO-045', 'published'),
  ('MO-CL-006', 'corp_loan', 'corporate_general_other', '一般公司风险暴露', 22, 'MO-SA-2026.1', '交易对手 = 公司，且未命中以上两条（兜底）', '公司风险暴露', '一般公司风险暴露', '100%', 'CL-MO-045', 'published'),
  ('MO-BD-001', 'bond', 'sovereign', '对主权及中央银行的暴露', 10, 'MO-SA-2026.1', '发行人类型 ∈ {我国中央政府, 我国中央银行, 其他主权国家或经济实体}', '主权及中央银行', '按外部评级分档', '0%–100%', 'CL-MO-015', 'published'),
  ('MO-BD-002', 'bond', 'covered_bond', '合格资产担保债券', 11, 'MO-SA-2026.1', '工具 = 资产担保债券 AND 资产池仅含合格资产 AND 资产池名义价值比 ≥ 110% AND 每半年可取得披露', '资产担保债券', '合格 / 不合格', '10% 或回退交易对手', 'CL-MO-050', 'published'),
  ('MO-BD-003', 'bond', 'mdb_qualified', '对合格多边开发银行的暴露', 12, 'MO-SA-2026.1', '发行人类型 = 多边开发银行 AND 交易对手名称 ∈ 合格名单 13 家', '多边开发银行', '合格多边开发银行', '0%', 'CL-MO-018', 'published'),
  ('MO-IB-001', 'ib_call', 'fi_bank', '对商业银行的暴露', 10, 'MO-SA-2026.1', '交易对手 = 商业银行 AND 是否适用 = 适用，按资本达标情况与审计意见分 A+/A/B/C 档', '商业银行风险暴露', '第一档 / 第二档', '20%–150%', 'CL-MO-022', 'published'),
  ('MO-IB-002', 'ib_call', 'fi_other', '对其他金融机构的暴露', 11, 'MO-SA-2026.1', '交易对手 ∈ {其他金融机构, 开发性金融机构, 政策性银行} AND 是否次级债权 = 否', '其他金融机构', '短期 / 中长期', '20% / 100%', 'CL-MO-022', 'published'),
  ('MO-IT-001', 'ib_time', 'fi_bank', '对商业银行的暴露', 10, 'MO-SA-2026.1', '交易对手 = 商业银行，按整个存放期判断短期档（≤3 个月）或中长期档', '商业银行风险暴露', '第一档 / 第二档', '20%–50%', 'CL-MO-022', 'published'),
  ('MO-OB-001', 'off_bs', 'regulatory_retail', '监管零售风险暴露', 10, 'MO-SA-2026.1', '交易对手 ∈ {自然人, 独资企业, 合伙制企业} AND 对单一债务人暴露 ≤ 1000万 AND 占全行比例 ≤ 0.5%', '监管零售组合', '监管零售风险暴露', '75%', 'CL-MO-042', 'published'),
  ('MO-OB-002', 'off_bs', 'corporate_general', '公司风险暴露', 11, 'MO-SA-2026.1', '交易对手 = 公司，按中小企业 / 投资级 / 一般分档', '公司风险暴露', '中小企业 / 投资级 / 一般', '75%–100%', 'CL-MO-045', 'published');
